// Command graphqlschema writes the GraphQL schema, packages/graphql/schema.graphql, from the Go
// registrations of the modules (ADR-0020). It imports neither gqlgen nor the generated executor,
// and no driver: `just generate` builds it with CGO_ENABLED=0 before gqlgen regenerates the
// executor from its output.
package main

import (
	"flag"
	"fmt"
	"os"

	"github.com/wilfriedago/tigerbeetle-platform/apps/api/internal/platform/graphqlschema"
	"github.com/wilfriedago/tigerbeetle-platform/apps/api/internal/transport/graphql/schema"
)

// header opens the generated file.
const header = "# Generated by cmd/graphqlschema from the Go registrations (ADR-0020). Do not edit.\n\n"

func main() {
	out := flag.String("out", "", "file to write the schema to; standard output when empty")
	flag.Parse()

	if err := run(*out); err != nil {
		fmt.Fprintln(os.Stderr, "graphqlschema:", err)
		os.Exit(1)
	}
}

func run(out string) error {
	sdl, err := build()

	if err != nil {
		return err
	}

	if out == "" {
		_, err = os.Stdout.Write(sdl)
		return err
	}

	if err := os.WriteFile(out, sdl, 0o644); err != nil { //nolint:gosec // the schema is a public file
		return fmt.Errorf("write %s: %w", out, err)
	}

	return nil
}

func build() ([]byte, error) {
	s := graphqlschema.New()
	schema.RegisterAll(s)
	sdl, err := s.SDL()

	if err != nil {
		return nil, err
	}

	return append([]byte(header), sdl...), nil
}
